package com.example.campsitelottery

import com.google.zxing.BinaryBitmap
import com.google.zxing.RGBLuminanceSource
import com.google.zxing.common.HybridBinarizer
import com.google.zxing.qrcode.QRCodeReader
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * Documentation generated by Claude
 * Tests building, reading and encoding campsite QR links with [CampsiteQrCode].
 */
class CampsiteQrCodeTest {

    @Test
    fun linkFor_buildsTheAppLink() {
        assertEquals("campsitelottery://campsite/campsite_01", CampsiteQrCode.linkFor("campsite_01"))
    }

    @Test(expected = IllegalArgumentException::class)
    fun linkFor_rejectsInvalidIds() {
        CampsiteQrCode.linkFor("not/an id")
    }

    @Test
    fun campsiteIdFrom_readsBackTheId() {
        val id = "Ab3dEfGh1JkLmN0pQrSt"
        assertEquals(id, CampsiteQrCode.campsiteIdFrom(CampsiteQrCode.linkFor(id)))
    }

    @Test
    fun campsiteIdFrom_ignoresSurroundingSpaces() {
        assertEquals("campsite_01", CampsiteQrCode.campsiteIdFrom("  campsitelottery://campsite/campsite_01\n"))
    }

    @Test
    fun campsiteIdFrom_rejectsOtherQrCodes() {
        assertNull(CampsiteQrCode.campsiteIdFrom(null))
        assertNull(CampsiteQrCode.campsiteIdFrom(""))
        assertNull(CampsiteQrCode.campsiteIdFrom("campsite_01"))
        assertNull(CampsiteQrCode.campsiteIdFrom("https://example.com/campsite/campsite_01"))
        assertNull(CampsiteQrCode.campsiteIdFrom("campsitelottery://lottery/waitlist_01"))
        assertNull(CampsiteQrCode.campsiteIdFrom("campsitelottery://campsite/"))
        assertNull(CampsiteQrCode.campsiteIdFrom("campsitelottery://campsite/a/b"))
        assertNull(CampsiteQrCode.campsiteIdFrom("campsitelottery://campsite/campsite_01?x=1"))
        assertNull(CampsiteQrCode.campsiteIdFrom("not a link at all"))
    }

    @Test
    fun fileNameFor_usesTheCampsiteName() {
        assertEquals("pine-ridge-retreat-qr-code.png", CampsiteQrCode.fileNameFor("Pine Ridge Retreat"))
        assertEquals("raven-s-nest-qr-code.png", CampsiteQrCode.fileNameFor("  Raven's Nest!  "))
    }

    @Test
    fun fileNameFor_fallsBackWhenTheNameHasNoLettersOrDigits() {
        assertEquals("campsite-qr-code.png", CampsiteQrCode.fileNameFor(""))
        assertEquals("campsite-qr-code.png", CampsiteQrCode.fileNameFor("***"))
    }

    @Test
    fun fileNameFor_keepsLongNamesShort() {
        val name = CampsiteQrCode.fileNameFor("a".repeat(200))
        assertEquals("a".repeat(60) + "-qr-code.png", name)
    }

    @Test
    fun encode_producesAQrCodeThatDecodesToTheLink() {
        val link = CampsiteQrCode.linkFor("campsite_01")
        val matrix = CampsiteQrCode.encode(link, size = 300)
        val pixels = IntArray(matrix.width * matrix.height) { i ->
            if (matrix.get(i % matrix.width, i / matrix.width)) 0xFF000000.toInt() else 0xFFFFFFFF.toInt()
        }
        val bitmap = BinaryBitmap(HybridBinarizer(RGBLuminanceSource(matrix.width, matrix.height, pixels)))
        assertEquals(link, QRCodeReader().decode(bitmap).text)
    }
}
